export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  var scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.66, 0.78, 0.79);
  scene.environmentTexture = BABYLON.CubeTexture.CreateFromPrefilteredData("/images/textures/environment.env", scene);
  console.log(scene.environmentTexture);
  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(88), 10, BABYLON.Vector3.Zero(), scene);
  camera.inertia = 0.1;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.7;

  var skyboxMaterial = new BABYLON.SkyMaterial("skyMaterial", scene);
  skyboxMaterial.backFaceCulling = false;

  var skybox = BABYLON.Mesh.CreateBox("skyBox", 1000.0, scene);
  skybox.material = skyboxMaterial;

  let inclinationDirection = 1;
  let inclinationSpeed = 0.00005;
  skyboxMaterial.inclination = 0.5;

  scene.onBeforeRenderObservable.add(() => {
    skyboxMaterial.inclination += inclinationSpeed * inclinationDirection;

    if (skyboxMaterial.inclination > 0.5) {
      skyboxMaterial.inclination = 0.5;
      inclinationDirection = -1;
    } else if (skyboxMaterial.inclination < -0.5) {
      skyboxMaterial.inclination = -0.5;
      inclinationDirection = 1;
    }
  });

  await BABYLON.InitializeCSG2Async();

  // Create window frame using CSG
  const width = 2;
  const height = 2;
  const depth = 0.2;
  const diff = 0.1;

  let wall = BABYLON.MeshBuilder.CreateBox("wall", { width: 15, height: 8, depth: depth }, scene);
  const wallMat = new BABYLON.PBRMaterial("wallMat", scene);
  wallMat.albedoTexture = new BABYLON.Texture("/images/textures/wall.jpg", scene);
  wallMat.metallic = 0;
  wallMat.roughness = 1;
  wall.material = wallMat;
  wall.isPickable = false;

  const box_outer = BABYLON.MeshBuilder.CreateBox("box_out", { width: width, height: height, depth: depth }, scene);
  box_outer.position.y = 1;
  const box_inner = BABYLON.MeshBuilder.CreateBox("box_in", { width: width - diff * 2, height: height - diff * 2, depth: depth + diff * 2 }, scene);
  box_inner.position.y = 1;

  const outerCSG = BABYLON.CSG2.FromMesh(box_outer);
  const innerCSG = BABYLON.CSG2.FromMesh(box_inner);
  const windowCSG = outerCSG.subtract(innerCSG);
  const window = windowCSG.toMesh("box", scene, null, false, true);

  // Cleanup
  box_inner.dispose();
  box_outer.dispose();
  outerCSG.dispose();
  innerCSG.dispose();

  const glass = BABYLON.MeshBuilder.CreateBox("glass", { width: width - diff * 2.2, height: height - diff * 2, depth: depth }, scene);

  const glassMat = new BABYLON.PBRMaterial("glassMat", scene);
  glassMat.indexOfRefraction = 1.52; // Typical IOR for glass
  glassMat.alpha = 0.1; // Transparency
  glassMat.microSurface = 1.0; // Sharp reflections
  glassMat.reflectivityColor = new BABYLON.Color3(0.2, 0.2, 0.2); // Faint reflection
  glassMat.albedoColor = new BABYLON.Color3(0.85, 0.95, 1); // Slight blue tint
  glassMat.transparencyMode = BABYLON.PBRMaterial.PBRMATERIAL_GLASS;
  glassMat.environmentTexture = scene.environmentTexture; // Needed for reflection/refraction

  glass.material = glassMat;

  const windowMat = new BABYLON.PBRMaterial("windowMat", scene);
  windowMat.albedoTexture = new BABYLON.Texture("/images/textures/wooden.jpg", scene);
  windowMat.metallic = 0;
  windowMat.roughness = 1;
  window.material = windowMat;

  const gl = new BABYLON.GlowLayer("glow", scene);
  gl.intensity = 0.4;

  const handleOffsets = {
    right: new BABYLON.Vector3(1.25, 0, 0),
    left: new BABYLON.Vector3(-1.25, 0, 0),
    top: new BABYLON.Vector3(0, 1.25, 0),
    bottom: new BABYLON.Vector3(0, -1.25, 0),
    // front: new BABYLON.Vector3(0, 0, 0.125),
    // back: new BABYLON.Vector3(0, 0, -0.125),
  };

  const directions = Object.keys(handleOffsets);
  const handles = [];

  const MIN_SIZE = 0.3;

  directions.forEach((dir) => {
    const offset = handleOffsets[dir].clone();

    const handle = BABYLON.MeshBuilder.CreateBox(`handle_${dir}`, { size: 0.1 }, scene);
    handle.isPickable = true;
    handle.renderingGroupId = 1;

    const handleMat = new BABYLON.StandardMaterial("handle_mat", scene);
    handleMat.emissiveColor = new BABYLON.Color3(0.1, 0.34, 0.65);
    handle.material = handleMat;
    handles.push({ mesh: handle, offset: offset });

    const axis =
      dir === "left" || dir === "right"
        ? new BABYLON.Vector3(1, 0, 0)
        : dir === "top" || dir === "bottom"
        ? new BABYLON.Vector3(0, 1, 0)
        : new BABYLON.Vector3(0, 0, 1); // front/back

    handle.addBehavior(new BABYLON.PointerDragBehavior({ dragAxis: axis }));

    const dragBehavior = handle.behaviors[0];

    dragBehavior.onDragObservable.add((event) => {
      const delta = event.dragDistance;

      // window, glass 둘 다 vertex 업데이트
      moveVertices(window, delta, dir);
      moveVertices(glass, delta, dir);

      wall.dispose();
      wall = updateWallWithWindowHole(window);
    });

    dragBehavior.onDragEndObservable.add(() => {
      //   originalPositions = window.getVerticesData(BABYLON.VertexBuffer.PositionKind).slice();
    });
  });

  /**
   * 1. 버텍스 위치 데이터 가져오기
   * mesh.getVerticesData(...)로 정점 배열을 가져옴
   * 2. 최소/최대 좌표 계산
   * 메시의 AABB(바운딩 박스)를 기준으로 특정 방향의 "끝 정점"을 판단
   * 3. 해당 방향의 정점만 이동
   * 예를 들어 "오른쪽"으로 창을 키우려면 오른쪽 끝에 있는 정점들만 +delta만큼 이동
   * 4. 버텍스 위치 업데이트
   * 변경된 정점 데이터를 메시로 다시 적용하고, 바운딩 박스를 새로고침
   */

  const moveVertices = (mesh, delta, dir) => {
    let positions = mesh.getVerticesData(BABYLON.VertexBuffer.PositionKind);
    if (!positions) return;

    const min = { x: Infinity, y: Infinity, z: Infinity };
    const max = { x: -Infinity, y: -Infinity, z: -Infinity };

    for (let i = 0; i < positions.length; i += 3) {
      const x = positions[i],
        y = positions[i + 1],
        z = positions[i + 2];
      if (x < min.x) min.x = x;
      if (x > max.x) max.x = x;
      if (y < min.y) min.y = y;
      if (y > max.y) max.y = y;
      if (z < min.z) min.z = z;
      if (z > max.z) max.z = z;
    }

    const axisIndex = dir === "left" || dir === "right" ? 0 : dir === "top" || dir === "bottom" ? 1 : 2;

    const isMax = dir === "right" || dir === "top" || dir === "front";
    const minVal = min[["x", "y", "z"][axisIndex]];
    const maxVal = max[["x", "y", "z"][axisIndex]];

    if (delta < 0 && maxVal - minVal < MIN_SIZE) return;

    for (let i = 0; i < positions.length; i += 3) {
      const val = positions[i + axisIndex];
      const compare = isMax ? maxVal : minVal;
      if (Math.abs(val - compare) < diff + 0.01) {
        positions[i + axisIndex] += delta;
      }
    }

    mesh.setVerticesData(BABYLON.VertexBuffer.PositionKind, positions, true);
    mesh.refreshBoundingInfo();
  };

  const MARGIN = 0.1;

  scene.onBeforeRenderObservable.add(() => {
    // AABB (Bounding Box) 기준으로 위치 재계산
    const boundingInfo = window.getBoundingInfo();
    const min = boundingInfo.boundingBox.minimumWorld;
    const max = boundingInfo.boundingBox.maximumWorld;

    handles.forEach(({ mesh, offset }) => {
      let position = new BABYLON.Vector3(
        offset.x === 0 ? (min.x + max.x) / 2 : offset.x > 0 ? max.x + MARGIN : min.x - MARGIN,
        offset.y === 0 ? (min.y + max.y) / 2 : offset.y > 0 ? max.y + MARGIN : min.y - MARGIN,
        offset.z === 0 ? (min.z + max.z) / 2 : offset.z > 0 ? max.z + MARGIN : min.z - MARGIN
      );
      mesh.position.copyFrom(position);
    });
  });

  function updateWallWithWindowHole(windowMesh) {
    const wallBox = BABYLON.MeshBuilder.CreateBox("wall", { width: 15, height: 8, depth: depth }, scene);
    wallBox.position = BABYLON.Vector3.Zero();

    // 현재 window의 bounding box를 기반으로 inner box 생성
    const bounds = windowMesh.getBoundingInfo().boundingBox;
    const min = bounds.minimum;
    const max = bounds.maximum;

    const holeWidth = max.x - min.x;
    const holeHeight = max.y - min.y;
    const holeDepth = 0.25;

    const holeBox = BABYLON.MeshBuilder.CreateBox(
      "holeBox",
      {
        width: holeWidth,
        height: holeHeight,
        depth: holeDepth,
      },
      scene
    );
    holeBox.position = bounds.centerWorld.clone();

    const wallCSG = BABYLON.CSG2.FromMesh(wallBox);
    const holeCSG = BABYLON.CSG2.FromMesh(holeBox);
    const wallWithHoleCSG = wallCSG.subtract(holeCSG);
    const newWall = wallWithHoleCSG.toMesh("wallWithHole", scene, null, false, true);
    newWall.material = wallMat;
    newWall.isPickable = false;

    // cleanup
    wallBox.dispose();
    holeBox.dispose();

    return newWall;
  }

  moveVertices(window, 0.1, "right");
  moveVertices(glass, 0.1, "right");
  wall.dispose();
  wall = updateWallWithWindowHole(window);

  return scene;
}
